// GUARDRAIL DE ENTRADA · valida el mensaje antes de que llegue al agente
const body = $input.first().json.body || {};
const msg = String(body.message || '').trim();
const reglas = [
  { id: 'vacio', test: m => m.length === 0,
    resp: 'No recibí ninguna pregunta. ¿En qué te ayudo con tu matrícula, notas o proyección?' },
  { id: 'longitud', test: m => m.length > 1500,
    resp: 'Tu mensaje es muy largo. Resúmelo en menos de 1.500 caracteres, por favor.' },
  { id: 'inyeccion_prompt', test: m => /(ignora|olvida|omite|salta).{0,30}(instrucciones|reglas|indicaciones|restricciones)|system prompt|prompt del sistema|revela (tu|el|las) (prompt|instrucciones)|jailbreak|modo (desarrollador|dios)|\bDAN\b|ahora eres|act[uú]a como (si no|un hacker)/i.test(m),
    resp: 'No puedo cambiar mis reglas de funcionamiento. Pregúntame sobre tu matrícula, notas, proyección o recomendaciones.' },
  { id: 'datos_sensibles', test: m => /\b(?:\d[ -]?){13,19}\b/.test(m) || /(contrase[ñn]a|password|clave)\s*[:=]/i.test(m),
    resp: 'Por tu seguridad, no compartas contraseñas ni números de tarjeta en el chat.' },
  { id: 'lenguaje_ofensivo', test: m => /\b(idiota|est[uú]pid[oa]|imb[eé]cil|malparid[oa]|gonorrea|hijueputa)\b/i.test(m),
    resp: 'Mantengamos una conversación respetuosa. ¿En qué te ayudo con tu carrera?' },
  { id: 'deshonestidad_academica', test: m => /(hazme|resu[eé]lveme|responde(me)?) (el|mi) (examen|parcial|quiz)|c[oó]mo (hago |hacer )?trampa|copiar(me)? en el (examen|parcial)|(cambiar|modificar|alterar) (mis|las) notas en el sistema/i.test(m),
    resp: 'No puedo ayudarte con trampa académica. Sí puedo explicarte el tema paso a paso para que lo prepares.' },
];
const hit = reglas.find(r => r.test(msg));
return [{ json: {
  sessionId: String(body.sessionId || 'anonimo').slice(0, 64),
  studentId: String(body.studentId || '').replace(/[^0-9A-Za-z-]/g, '').slice(0, 20),
  message: msg.slice(0, 1500),
  context: body.context || {},
  bloqueado: !!hit,
  motivo: hit ? hit.id : null,
  respuesta_guardrail: hit ? hit.resp : null,
} }];

// GUARDRAIL DE SALIDA · revisa la respuesta del agente antes de enviarla
let reply = String($input.first().json.output || '').trim();
const flags = [];
if (!reply) { reply = 'No pude generar una respuesta. ¿Puedes reformular la pregunta?'; flags.push('respuesta_vacia'); }
if (/(CONTEXTO ACAD[ÉE]MICO|REGISTRO INSTITUCIONAL|Eres ATLAS|system prompt)/i.test(reply)) {
  reply = 'Lo siento, no puedo compartir mi configuración interna. ¿Te ayudo con tus notas o tu proyección?'; flags.push('fuga_de_prompt');
}
const antes = reply;
reply = reply.replace(/\b(?:\d[ -]?){13,19}\b/g, '[dato oculto]');
if (reply !== antes) flags.push('dato_sensible_oculto');
if (/\bnota[^.\n]{0,40}\b([6-9]|[1-9]\d)[,.]\d\b/i.test(reply)) flags.push('nota_fuera_de_escala_0_5');
if (reply.length > 1800) { reply = reply.slice(0, 1800).replace(/\s+\S*$/, '') + '…'; flags.push('truncada'); }
return [{ json: { reply, guardrails: flags } }];
